import type {ExtWebSocket} from './connectionHandler.js';
import type {SessionStore} from '../../types/sessionStore.js';
import type {SessionSummary} from '../../types/sessionStore.js';
import type {SessionSummaryFrame, IncomingMessage...} from '../../types/messages.js';

export function createMessageHandler(orchestrator: ChatOrchestrator, sessionStore: SessionStore) {
  const lock = new PerSessionLock();
  return function handleMessage(
    ws: ExtWebSocket,
    session: ChatSession,
    rawMessage: unknown,
    signal?: AbortSignal
  ): Promise<void> {
    const validation = validateMessage(rawMessage);
    if (isUserMessageFrame(rawMessage)) {
      return lock.run(session.sessionId, () => answerInTurn(ws, session, orchestrator, validation, signal));
    }
    // A history request is not a turn: it mutates nothing, so it answers beside ping instead of queueing behind a streaming answer.
    return wsErrorHandler(ws, async () => answerFrame(ws, sessionStore, validation));
  };
}
```

