// The user id is the connection's, read off the upgrade: a frame naming another user still asks for its own list.
async function answerListSessions(
  ws: ExtWebSocket,
  sessionStore: SessionStore,
  frame: ListSessionsMessage
): Promise<void> {
  // A store holding to the five original members has no listFor, and an empty list is what "nothing to list" reads as.
  if (!sessionStore.listFor) {
    sendSessionList(ws, []);
    return;
  }
  try {
    const summaries = await sessionStore.listFor(ws.userId, {limit: frame.limit, before: frame.before});
