  } catch (error) {
    const detail = error instanceof Error ? error.message : 'Unknown error';
    // The detail stays in the log: a client that rendered "database offline" as a row has been told nothing.
    log.error('ws', 'conversation list failed', {userId: ws.userId, error: detail});
    sendError(ws, ErrorCodes.SERVER_ERROR, 'Could not list conversations');
  }
